custom_css:
/* - - - - - - - - - - - - - - - - -

    "Moonlit Echoes" 月下回聲
    ₊*.⊹ ⁎✧‧₊˚

    Presented by Rivelle,
    dedicated to all the lovely souls.

   - - - - - - - - - - - - - - - - - */

/* Cloufam: жидкое стекло, Liquid Glass — Apple iOS 26: прозрачная заливка с
   вибрацией фона, светящаяся кромка (inset highlight — спекуляр), мягкая тень.
   Геометрия автора (Moonlit Echoes, Rivelle, AGPL-3.0) не трогается.
   Селектор утяжелён (.mes_block.mes_block). */

/* --- Сообщения: стекло плотное, текст читается --- */
body #chat .mes .mes_block.mes_block {
    background-color: transparent !important;
    background-image: linear-gradient(135deg, rgba(140, 175, 255, 0.34) 0%, rgba(80, 72, 195, 0.44) 46%, rgba(14, 20, 54, 0.56) 100%) !important;
    backdrop-filter: blur(26px) saturate(185%) brightness(1.06) !important;
    -webkit-backdrop-filter: blur(26px) saturate(185%) brightness(1.06) !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.28), inset 0 -1px 0 rgba(255,255,255,0.08), 0 16px 38px rgba(3,6,22,0.46) !important;
    border: none !important;
}
body #chat .mes[is_user="true"] .mes_block.mes_block {
    background-image: linear-gradient(135deg, rgba(160, 196, 255, 0.40) 0%, rgba(96, 88, 210, 0.48) 46%, rgba(20, 28, 64, 0.58) 100%) !important;
}

/* Плита под текстом: тёмная пластинка из темы автора мешает читать стекло. */
body #chat .mes .mes_text {
    background-color: transparent !important;
    background-image: none !important;
    border: 0 !important;
    box-shadow: none !important;
}
body #chat .mes .mes_text q { color: var(--SmartThemeQuoteColor); font-style: normal; }
body #chat .mes .mes_text em, body #chat .mes .mes_text i { color: var(--SmartThemeEmColor); }

/* Край inset-тени стекла может залезать на аватарку, потому что .mes_block
   рисуется поверх неё. Убираем перекрытие: аватарка должна быть выше стекла. */
body #chat .mes .mesAvatarWrapper {
    position: relative;
    z-index: 2;
}
body #chat .mes .mes_block {
    position: relative;
    z-index: 1;
}

/* --- Фон страницы: аврора для прозрачных обоев --- */
body {
    background-color: #070b1c !important;
    background-image:
        radial-gradient(1200px 700px at 12% -10%, rgba(56, 104, 200, 0.34) 0%, rgba(7,11,28,0) 62%),
        radial-gradient(900px 620px at 88% 8%, rgba(122, 74, 200, 0.28) 0%, rgba(7,11,28,0) 60%),
        radial-gradient(1100px 800px at 50% 108%, rgba(34, 64, 148, 0.30) 0%, rgba(7,11,28,0) 64%),
        linear-gradient(160deg, #0a1026 0%, #131a3c 46%, #090d20 100%) !important;
    background-attachment: fixed !important;
}

/* --- Панели ST: ящики, расширения, меню, окно настроек --- */
body .drawer-content,
body .welcomePanel,
body #character_popup,
body .popup,
body #extensionsMenu {
    background-color: transparent !important;
    background-image: linear-gradient(135deg, rgba(140, 175, 255, 0.28) 0%, rgba(72, 64, 180, 0.38) 48%, rgba(12, 17, 48, 0.50) 100%) !important;
    backdrop-filter: blur(26px) saturate(185%) brightness(1.06) !important;
    -webkit-backdrop-filter: blur(26px) saturate(185%) brightness(1.06) !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.24), inset 0 -1px 0 rgba(255,255,255,0.06), 0 18px 44px rgba(3,6,22,0.48) !important;
    border: none !important;
}
body .drawer-content .inline-drawer {
    background-color: rgba(112, 132, 220, 0.07);
}
body .drawer-content .inline-drawer .inline-drawer-content {
    background-color: rgba(10, 14, 32, 0.18);
}
